import type { Post as PostRow } from '@/prisma/client';
import type { PostDocument } from '@/models/post';

/** A post row as stored in Postgres (`posts`). Nullable columns are the fields legacy Mongo
 * documents could miss. */
export type IPost = PostRow;

type NullableKeys<T> = { [K in keyof T]-?: null extends T[K] ? K : never }[keyof T];

// Columns with a database default are optional on input but always set on output
type PostDefaultedFields =
	'id' | // generated by Post.create when not given
	'body' |
	'is_autopost' |
	'is_community_private_autopost' |
	'is_spoiler' |
	'is_app_jumpable' |
	'empathy_count' |
	'country_id' |
	'language_id' |
	'reply_count' |
	'verified' |
	'removed' |
	'search_key' |
	'yeahs';

type PostOptionalFields = PostDefaultedFields | NullableKeys<IPost>;

export type IPostInput = Omit<IPost, PostOptionalFields> & Partial<Pick<IPost, PostOptionalFields>>;

export type HydratedPostDocument = PostDocument;
